return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Portuguese (Portugal)','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 20:08+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'pt_PT','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Roteamento multilíngue, meta tags de SEO e ferramentas de conteúdo AI para WordPress. Combina deteção de idioma, roteamento de URLs, hreflang, descrições meta e recursos de excerto, meta e tradução alimentados por IA.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Traduzir','Lingua Forge — Quick Translate'=>'Lingua Forge — Tradução rápida','Informative'=>'Informativo','Persuasive'=>'Persuasivo','Storytelling'=>'Contar histórias','Technical'=>'Técnico','Conversational'=>'Conversacional','Permission denied.'=>'Permissão negada.','Cannot determine target language from slug.'=>'Não foi possível determinar o idioma de destino a partir do slug.','Invalid post type.'=>'Tipo de publicação inválido.','Invalid or primary language.'=>'Idioma inválido ou principal.','Template not found or not stored in the database.'=>'Modelo não encontrado ou não armazenado na base de dados.','Template has no content.'=>'O modelo não tem conteúdo.','No internal links found to update.'=>'Nenhum link interno encontrado para atualizar.','%d link updated.'=>'%d link atualizado.' . "\0" . '%d links atualizados.','No language-specific template parts found to map.'=>'Nenhuma parte do modelo específica de idioma encontrada para mapear.','No template part references needed updating.'=>'Nenhuma referência de parte do modelo precisa ser atualizada.','%d part reference updated.'=>'%d referência de parte atualizada.' . "\0" . '%d referências de partes atualizadas.','Invalid language.'=>'Idioma inválido.','Template part not found or not stored in the database.'=>'Parte do modelo não encontrada ou não armazenada na base de dados.','Template part has no content.'=>'A parte do modelo não tem conteúdo.','No navigation references needed updating.'=>'Nenhuma referência de navegação precisa ser atualizada.','%d navigation reference updated.'=>'%d referência de navegação atualizada.' . "\0" . '%d referências de navegação atualizadas.','No AI provider configured.'=>'Nenhum provedor de IA configurado.','Missing pattern name or language.'=>'Nome do padrão ou idioma ausente.','Pattern not found.'=>'Padrão não encontrado.','Pattern has no content to translate.'=>'O padrão não tem conteúdo para traduzir.','AI provider returned an empty response.'=>'O provedor de IA retornou uma resposta vazia.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Padrão traduzido e salvo. Copie o conteúdo para o seu post CPT através do inseridor de padrões do editor de blocos ou use-o como ponto de partida para um Bloco Reutilizável.','Invalid template type.'=>'Tipo de modelo inválido.','Template "%s" already exists.'=>'Modelo "%s" já existe.','"%s" created.'=>'"%s" criado.','Invalid template part.'=>'Parte do modelo inválida.','Template part "%s" already exists.'=>'Parte do modelo "%s" já existe.','"%1$s" created. %2$d template updated.'=>'"%1$s" criado. %2$d modelo atualizado.' . "\0" . '"%1$s" criado. %2$d modelos atualizados.','Page'=>'Página','Single'=>'Único','Search'=>'Pesquisar','Search Results'=>'Resultados da pesquisa','Archive'=>'Arquivo','Front Page'=>'Página inicial','Single: %s'=>'Singular: %s','Single %s'=>'Singular %s','Archive: %s'=>'Arquivo: %s','%s Archive'=>'%s Arquivo','No source content found to translate.'=>'Não foi encontrado conteúdo fonte para traduzir.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Traduzido. Revise no Editor do Site — links internos, URLs de navegação e slugs de modelos não são atualizados automaticamente.','Navigation not found.'=>'Navegação não encontrada.','Navigation has no content to translate.'=>'Navegação não tem conteúdo para traduzir.','"%1$s %2$s" saved.'=>'"%1$s %2$s" guardado.','Translate page…'=>'Traduzir página…','Generate content…'=>'Gerar conteúdo…','AI Behaviour Preset'=>'Predefinição de Comportamento de IA','Custom'=>'Personalizado','Global default (%s)'=>'Padrão global (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Sobrescreve a predefinição de IA para Tradução e Geração de Conteúdo nesta página. Instruções personalizadas de prompt em todo o site (Configurações → Comportamento) são sempre adicionadas a cada solicitação, independentemente desta seleção.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Sobrescreve a predefinição de IA para Tradução e Geração de Conteúdo nesta página. Todas as outras funcionalidades sempre usam a predefinição global.','Close'=>'Fechar','Translate missing'=>'Falta tradução','From'=>'De','Retranslate'=>'Retraduzir','Translating…'=>'Traduzindo…','Retranslating…'=>'Retraduzindo…','✓ Done'=>'✓ Concluído','Error'=>'Erro','Navigation posts are translated via the Router tab, not this button.'=>'As publicações de navegação são traduzidas via a aba Router, não por este botão.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Criar traduções para o tipo de publicação "%s" requer uma integração ativa. Por favor, assegure-se de que a integração necessária está instalada e ativa.','No %s version found in this translation group.'=>'Nenhuma versão de %s encontrada neste grupo de tradução.','AI Usage'=>'Uso de IA','Today'=>'Hoje','Last 7 days'=>'Últimos 7 dias','Last 30 days'=>'Últimos 30 dias','All time'=>'Todo o tempo','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Consumo de tokens agrupado por funcionalidade, provedor e modelo. Registrado em cada chamada bem-sucedida de IA; os testes de conexão são deliberadamente excluídos para não distorcer os totais. A tabela subjacente agrega diariamente — escolha uma janela abaixo para visualizá-la.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Ainda não há uso de IA registrado. Assim que um editor executar uma tradução, gerar uma meta descrição ou usar qualquer outra funcionalidade de IA, os totais aparecerão aqui.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Nenhum uso de IA registrado na janela selecionada (%s). Selecione um intervalo mais amplo acima.','Feature'=>'Funcionalidade','Provider'=>'Provedor','Model'=>'Modelo','Requests'=>'Solicitações','Input tokens'=>'Tokens de entrada','Output tokens'=>'Tokens de saída','Total tokens'=>'Tokens totais','Total'=>'Total','API Keys'=>'Chaves API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'As chaves são criptografadas com AES-256-CBC antes de serem armazenadas na base de dados do WordPress. O segredo de criptografia é derivado dos seus salts de autenticação do WordPress (wp-config.php), portanto, chaves em texto simples nunca entram na base de dados.','API Key'=>'Chave API','Paste your API key…'=>'Cole sua chave API…','✓ Configured'=>'✓ Configurado','✗ Not configured'=>'✗ Não configurado','Test connection'=>'Testar conexão','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Deixe em branco para manter a chave existente. Insira um novo valor para substituí-la.','Remove stored key'=>'Remover chave armazenada','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Esta chave está atualmente fornecida por um servidor %s e não pode ser removida aqui. Insira uma nova chave acima para substituí-la por um valor do banco de dados.','environment variable'=>'variável de ambiente','PHP constant'=>'constante PHP','Alternative (server-side):'=>'Alternativa (lado do servidor):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Você também pode definir chaves como constantes ou variáveis de ambiente (por exemplo, no wp-config.php). Essas fontes são usadas automaticamente como fallback quando nenhuma chave do banco de dados está armazenada.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Para usar um segredo de criptografia personalizado (em vez do valor derivado wp_salt), adicione isto ao wp-config.php:','Unknown provider.'=>'Provedor desconhecido.','No API key configured for this provider.'=>'Nenhuma chave API configurada para este provedor.','Could not instantiate the provider.'=>'Não foi possível instanciar o provedor.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'O provedor não retornou texto. Verifique o log de erros do WordPress para a razão detalhada da falha.','Behavior'=>'Comportamento','Block Editor'=>'Editor de Blocos','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'A Lingua Forge restringe por padrão dois recursos do Gutenberg para manter o comportamento editorial consistente entre idiomas. Opte aqui quando precisar de capacidades completas do Gutenberg / FSE.','Block locking'=>'Bloqueio de blocos','Allow editors to lock individual blocks'=>'Permitir que editores bloqueiem blocos individuais','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Reativa o canLockBlocks do Gutenberg. Útil para modelos editoriais que precisam impedir que colaboradores movam ou excluam blocos específicos.','Template mode'=>'Modo de modelo','Allow Gutenberg template-editing mode on post screens'=>'Permitir modo de edição de modelos do Gutenberg nas telas de postagem','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Reativa supportsTemplateMode. Fundamental para fluxos de trabalho de Edição Completa do Site onde as substituições de modelos ao nível da postagem são intencionais.','Compliance Preset'=>'Predefinição de conformidade','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Modo de preservação rigorosa para conteúdo legal, regulatório, médico ou técnico. Quando ativado, cada recurso de IA usa uma temperatura de amostragem baixa e adiciona o adendo abaixo ao seu prompt do sistema — terminologia, números de artigos, unidades, nomes de marcas e linguagem regulatória são preservados exatamente, em vez de parafraseados.','Global AI preset'=>'Predefinição global de IA','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, por recurso','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Define o comportamento padrão de IA para todos os recursos em todo o site. Postagens individuais podem sobrescrever isso para Tradução e Geração de Conteúdo via a caixa meta Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'O padrão usa a temperatura ajustada de cada recurso: Tradução T=0.2 (preciso), Tradução Rápida T=0.4, Gerador de Conteúdo T=0.6 (criativo). Os outros predefinições aplicam uma única temperatura fixa a todos os recursos.','Technical / Scientific instructions'=>'Instruções técnicas / científicas','Legal / Compliance instructions'=>'Instruções legais / de conformidade','Creative / Marketing instructions'=>'Instruções criativas / de marketing','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Deixe em branco para usar o padrão embutido. Limpar uma substituição salva restaura o padrão na próxima gravação.','View built-in default'=>'Ver padrão embutido','Translation Memory'=>'Memória de tradução','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Armazena equivalentes traduzidos ao nível do bloco para que conteúdo reutilizável (rodapés compartilhados, barras laterais, acordeões, seções legais com muitas cláusulas) não pague uma chamada de API toda vez. Quando ativado, o fluxo de tradução analisa cada postagem em blocos, verifica cada bloco no cache e envia apenas blocos não armazenados em cache para a IA em uma única solicitação em lote. Edições de glossário e alterações na predefinição de conformidade invalidam automaticamente as traduções em cache afetadas. Veja estatísticas e limpe o cache em Manutenção.','Enable block-level translation cache reuse across posts'=>'Permitir reutilização do cache de tradução ao nível do bloco entre postagens','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Atualmente ignorado para postagens que usam atributos de espaço reservado de comentário de bloco (campos de resumo wp:details, etc.) — eles passam para o caminho de tradução de chamada única existente.','General'=>'Geral','Light'=>'Leve','Meta Description, Excerpt Generator'=>'Descrição Meta, Gerador de Resumo','Quality'=>'Qualidade','Translation, Content Generator'=>'Tradução, Gerador de Conteúdo','Active Provider'=>'Provedor Ativo','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Atualmente herdado da constante %s. Selecionar um valor aqui irá sobrescrevê-lo.','Models'=>'Modelos','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Os recursos são agrupados em dois níveis. Insira o identificador exato do modelo para cada nível e provedor. Deixe um campo em branco para usar o padrão embutido (mostrado como espaço reservado). Apenas os modelos do provedor ativo são chamados em tempo de execução — configure os outros com antecedência se planeja trocar.','active'=>'ativo','overridden'=>'sobrescrito','Tip: to reset a model to the built-in default, clear the field and save.'=>'Dica: para redefinir um modelo para o padrão embutido, limpe o campo e salve.','Glossary'=>'Glossário','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tabela de terminologia gerida pelo utilizador por par de línguas. As entradas são adicionadas ao prompt do sistema de tradução para que a IA utilize termos preferidos de forma consistente — fundamental para o vocabulário do domínio ("kWp", "PPA", "ponto de interligação"), nomes de marcas que não devem ser traduzidos e formulações regulatórias padronizadas. Ambos os campos de idioma são opcionais: deixe o "Idioma de origem" em branco para aplicar a entrada independentemente do idioma de origem; deixe o "Idioma de destino" em branco para aplicá-la a todos os idiomas de destino de uma só vez.','Glossary entry added.'=>'Entrada do glossário adicionada.','Glossary entry removed.'=>'Entrada do glossário removida.','Could not add entry: source term and target term are required.'=>'Não foi possível adicionar a entrada: termo de origem e termo de destino são obrigatórios.','Could not save the glossary entry.'=>'Não foi possível guardar a entrada do glossário.','Source language'=>'Idioma de origem','— Any —'=>'— Qualquer —','Target language'=>'Idioma de destino','— Any target —'=>'— Qualquer destino —','Filter'=>'Filtro','Reset'=>'Reiniciar','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Nenhuma entrada do glossário corresponde ao filtro atual. Limpe o filtro para ver todas as entradas ou adicione uma nova entrada abaixo.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Ainda não há entradas no glossário. Adicione uma abaixo para começar a aplicar terminologia nas traduções.','Source term'=>'Termo de origem','Target term'=>'Termo de destino','Source lang'=>'Idioma de origem','Target lang'=>'Idioma de destino','Notes'=>'Notas','any'=>'qualquer','Delete this glossary entry?'=>'Deseja excluir esta entrada do glossário?','Delete'=>'Excluir','Add new entry'=>'Adicionar nova entrada','The phrase as it appears in the source text.'=>'A frase como aparece no texto de origem.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Como deve aparecer na tradução. Digite o mesmo valor do termo de origem para instruir a IA a preservá-lo exatamente.','— Any source language —'=>'— Qualquer idioma de origem —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Deixe em branco para nomes de marcas e termos independentes de idioma que devem ser preservados independentemente do idioma de origem.','— Any target language —'=>'— Qualquer idioma de destino —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Deixe em branco para aplicar esta entrada a todos os idiomas de destino — ideal para nomes de marcas, abreviaturas e termos que devem ser preservados exatamente em todas as traduções.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Contexto opcional para editores (por exemplo, "ASIC = Circuito Integrado Específico de Aplicação; manter em inglês em contextos técnicos").','Add entry'=>'Adicionar entrada','Limits'=>'Limites','Authors and above (edit_published_posts)'=>'Autores e superiores (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Colaboradores e superiores — padrão (edit_posts)','Editors and above (edit_others_posts)'=>'Editores e superiores (edit_others_posts)','Administrators only (manage_options)'=>'Apenas administradores (manage_options)','AI Limits & Security'=>'Limites e Segurança da IA','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limite o uso da IA que o site pode gerar e restrinja quais funções de usuário podem acionar chamadas pagas à IA. Sobrepõe-se ao limite de taxa por usuário (30 pedidos / minuto, codificado) que já protege contra loops descontrolados de um único usuário.','Daily request limit'=>'Limite diário de pedidos','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Limite máximo de pedidos de IA por dia UTC (conta traduções na Toolbar e revisões de blocos). O contador reinicia à meia-noite UTC. Defina como 0 para desativar o limite.','Minimum role'=>'Nível mínimo','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Menor capacidade do WordPress permitida para acionar recursos de IA. Restringir isso em sites com múltiplos autores impede que Colaboradores ou contas de teste executem chamadas pagas à IA. Pode sobrepor por recurso através do filtro linguaforge_required_capability.','Translation Limits'=>'Limites de Tradução','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Controle quanto conteúdo é enviado para a IA e quão grande pode ser a resposta. Deixe um campo em branco para usar o padrão interno (mostrado como espaço reservado). Aumente esses valores se páginas grandes estiverem sendo cortadas; reduza-os para diminuir custos de API.','Model tier'=>'Nível do modelo','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualidade (padrão — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Leve (rápido e econômico — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Qual nível de modelo usar para tradução de página inteira. A qualidade usa o modelo configurado na tabela Modelos acima e é recomendado para traduções precisas e de formato longo. Mude para Leve apenas se velocidade ou custo forem prioridade e o conteúdo for curto.','Max output tokens'=>'Máximo de tokens de saída','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Número máximo de tokens que a IA pode produzir numa única resposta de tradução. Se uma tradução for cortada silenciosamente no final, aumente este valor. Padrão: 16 000.','Max input characters'=>'Máximo de caracteres de entrada','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Número máximo de caracteres do conteúdo da publicação encaminhado para a IA. 0 significa sem limite — o conteúdo completo é sempre enviado (recomendado). Defina um valor diferente de zero apenas se o seu provedor tiver uma janela de contexto restrita. Um aviso é registrado no log de erros do PHP sempre que o conteúdo é cortado.','Quick Translation'=>' Tradução rápida','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'A Tradução rápida é usada para modo de fragmento/pedaço — passagens curtas traduzidas sob demanda a partir da barra de ferramentas, editor ou popovers de blocos. Usa uma configuração separada e mais leve do que a tradução de página inteira para manter as respostas rápidas e econômicas.','Light (default — fast and cost-effective)'=>'Leve (padrão — rápido e econômico)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Qualidade (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'O nível Leve usa o modelo rápido configurado na tabela de Modelos acima (padrão: Haiku / Flash). Mude para Qualidade se precisar da mesma precisão de tradução que o modo de página inteira para trechos.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Tokens máximos que a IA pode produzir por tradução rápida. Padrão: 2 000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Número máximo de caracteres aceitos do campo de entrada. Padrão: 8 000.','Content Generator'=>'Gerador de Conteúdo','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controla o orçamento de tokens e limites de entrada para o recurso Gerador de Conteúdo de IA. Deixe os campos em branco para usar os padrões integrados.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Tokens máximos que a IA pode produzir por execução de geração. Aumente se artigos completos estiverem sendo cortados. Padrão: 8 192.','Max hints characters'=>'Máximo de caracteres de dicas','Maximum characters read from the Hints field. Default: 2 000.'=>'Número máximo de caracteres lidos do campo de Dicas. Padrão: 2 000.','Max context characters'=>'Máximo de caracteres de contexto','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Número máximo de caracteres do conteúdo existente da publicação passado para a IA como contexto semente quando nenhuma Dica é fornecida. Padrão: 6 000.','Maintenance'=>'Manutenção','Language Overrides'=>'Substituições de idioma','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Carregue arquivos .mo compilados para substituir as strings do plugin de terceiros para locais específicos — por exemplo, uma tradução personalizada do VikBooking que usa "apartamento" em vez de "quarto". Os arquivos devem seguir a convenção de nomenclatura do WordPress: {textdomain}-{locale}.mo (exemplo: vikbooking-ca.mo). Eles são armazenados na pasta de uploads e sobrevivem às atualizações do plugin.','Override file uploaded successfully.'=>'Arquivo de substituição carregado com sucesso.','Override file deleted.'=>'Arquivo de substituição excluído.','No file was selected.'=>'Nenhum arquivo foi selecionado.','Only .mo files are accepted.'=>'Apenas arquivos .mo são aceitos.','The upload failed — please try again.'=>'Falha no upload — por favor, tente novamente.','Could not save the file. Check that the uploads folder is writable.'=>'Não foi possível salvar o arquivo. Verifique se a pasta de uploads é gravável.','Invalid filename.'=>'Nome de arquivo inválido.','Security check failed — file path is not permitted.'=>'Falha na verificação de segurança — caminho do arquivo não permitido.','An unknown error occurred.'=>'Ocorreu um erro desconhecido.','Text domain / locale'=>'Domínio de texto / localidade','Files'=>'Arquivos','Size'=>'Tamanho','Delete all files for this override (both .mo and .po)?'=>'Excluir todos os arquivos desta substituição (tanto .mo quanto .po)?','No override files uploaded yet.'=>'Ainda não foram carregados arquivos de substituição.','Upload .mo file'=>'Carregar arquivo .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Aceita apenas arquivos .mo compilados. O nome do arquivo deve seguir o padrão {textdomain}-{locale}.mo. Carregar um arquivo com o mesmo nome de um existente substituirá o mesmo.','Upload Override'=>'Carregar Substituição','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copiar para Armazenamento Seguro','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'O Loco Translate armazena suas traduções personalizadas em wp-content/languages/loco/ — um local que pode ser apagado silenciosamente por uma atualização do núcleo do WP, reinstalação do plugin ou se o próprio Loco Translate for removido. Copiar arquivos aqui os move para o diretório Lingua Forge i18n-overrides, que persiste através de todos esses eventos e é carregado automaticamente em cada solicitação.','File copied to safe storage successfully.'=>'Arquivo copiado para armazenamento seguro com sucesso.','Source file not found.'=>'Arquivo de origem não encontrado.','Could not copy the file. Check that the uploads folder is writable.'=>'Não foi possível copiar o arquivo. Verifique se a pasta de uploads é gravável.','Invalid file reference.'=>'Referência de arquivo inválida.','Type'=>'Tipo','✓ In safe storage'=>'✓ Em armazenamento seguro','Copy to safe storage'=>'Copiar para armazenamento seguro','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Ainda não foram encontrados arquivos personalizados do Loco Translate. Eles aparecem aqui assim que você salva uma tradução no Loco Translate.','AI Cache'=>'Cache de IA','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'O Lingua Forge armazena em cache traduções geradas por IA, meta descrições, trechos e conteúdo gerado por publicação para que entradas inalteradas não acionem uma chamada de API paga. Entradas em cache são invalidadas automaticamente quando seus inputs mudam. Limpe o cache manualmente para recuperar espaço no banco de dados, forçar uma re-sincronização após trocar de provedores ou editar modelos de prompt, ou solucionar problemas relacionados ao cache.','AI cache cleared. %d entry was removed.'=>'Cache de IA limpo. %d entrada foi removida.' . "\0" . 'Cache de IA limpo. %d entradas foram removidas.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Limpar todos os resultados de IA em cache? Solicitações futuras irão acionar chamadas de API novas até que o cache seja reconstruído.','Clear AI Cache'=>'Limpar cache de IA','Debug Files'=>'Arquivos de depuração','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Quando o registo de depuração está ativado (através do botão abaixo ou definindo LINGUAFORGE_AI_DEBUG no wp-config.php), os recursos de tradução de modelos e de tradução de modelos FSE escrevem os seus prompts de IA e respostas para o disco para resolução de problemas. Use esta seção para monitorar essa saída e limpá-la assim que tiver o que precisa — os ficheiros podem crescer rapidamente em páginas grandes. Configure o diretório de destino através do filtro linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Arquivos de depuração limpos. %d ficheiro foi removido.' . "\0" . 'Arquivos de depuração limpos. %d ficheiros foram removidos.','Debug logging enabled.'=>'Registo de depuração ativado.','Debug logging disabled.'=>'Registo de depuração desativado.','Debug logging'=>'Registo de depuração','Write AI prompts and responses to disk for troubleshooting'=>'Escrever prompts e respostas de IA no disco para resolução de problemas','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forçado ATIVADO pela constante LINGUAFORGE_AI_DEBUG no wp-config.php. Remova essa linha para controlar este botão a partir daqui.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forçado DESATIVADO pela constante LINGUAFORGE_AI_DEBUG no wp-config.php. Remova essa linha para controlar este botão a partir daqui.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Os ficheiros são guardados no diretório abaixo. Útil para diagnosticar problemas de tradução — desative assim que tiver o que precisa para evitar o acúmulo de ficheiros. Também pode forçar isto a partir do wp-config.php com `define( \'LINGUAFORGE_AI_DEBUG\', true );` que substitui o botão.','Currently:'=>'Atualmente:','✓ Enabled'=>'✓ Ativado','✗ Disabled'=>'✗ Desativado','Directory'=>'Diretório','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtre com linguaforge_debug_dir para redirecionar a saída de depuração para um local não público.','.txt file(s) in the directory'=>'.txt ficheiro(s) no diretório','Save Debug Setting'=>'Salvar configuração de depuração','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Eliminar todos os ficheiros .txt no diretório de depuração? O próprio diretório permanecerá para que futuras gravações de depuração continuem a ser feitas de forma limpa.','Clear Debug Files'=>'Limpar ficheiros de depuração','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Cache de tradução por bloco partilhado entre posts. Configure ativar/desativar em Configurações → Comportamento. As estatísticas abaixo mostram o que está atualmente em cache; limpar força cada bloco a ser re-traduzido na próxima solicitação (útil após atualizar modelos ou para recuperar espaço na base de dados).','Translation Memory cleared. %d cached block was removed.'=>'Memória de tradução limpa. %d bloco em cache foi removido.' . "\0" . 'Memória de tradução limpa. %d blocos em cache foram removidos.','Status'=>'Estado','— toggle in Settings → Behavior.'=>'— botão em Configurações → Comportamento.','Cached blocks'=>'Blocos em cache','Cumulative cache hits'=>'Hits cumulativos de cache','(avg %.1f hits/block)'=>'(média %.1f hits/bloco)','Oldest entry'=>'Entrada mais antiga','Newest entry'=>'Entrada mais recente','Approximate size'=>'Tamanho aproximado','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Limpar toda a Memória de Tradução? As traduções futuras reconstruirão o cache à medida que forem feitas.','Clear Translation Memory'=>'Limpar Memória de Tradução','Uninstall Behaviour'=>'Desinstalar Comportamento','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controla o que acontece quando um administrador remove o plugin de Plugins → Plugins instalados → Eliminar. As configurações do plugin e os caches de IA são sempre removidos. As atribuições de idioma e relações de tradução são mantidas por padrão para que uma desinstalação acidental ou uma reinstalação possam continuar de onde pararam.','Uninstall setting saved.'=>'Configuração de desinstalação guardada.','Delete content data on uninstall'=>'Eliminar dados de conteúdo na desinstalação','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Também eliminar atribuições de idioma, relações de tradução, descrições meta, glossário e Memória de Tradução quando o plugin for desinstalado','Warning:'=>'Aviso:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Se marcado, ao desinstalar o plugin, todos as atribuições de idioma, relações de tradução, descrições meta, predefinições de página, o glossário de IA e a Memória de Tradução serão apagados permanentemente de todos os posts neste site. Isto não pode ser desfeito. Deixe desmarcado a menos que esteja a remover totalmente o suporte multilíngue do site.','Save Uninstall Setting'=>'Salvar configuração de desinstalação','Router'=>'Roteador','Primary language saved.'=>'Idioma principal guardado.','Permalink rules flushed successfully.'=>'Regras de permalink limpas com sucesso.','Primary Language'=>'Idioma principal','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'O idioma principal é sempre servido na raiz do seu site — sem prefixo de URL em modo de caminho, sem subdomínio de idioma em modo de subdomínio. Todos os outros idiomas usam um prefixo de caminho /lang/ (exemplo: exemplo.com/de/) ou um subdomínio de idioma (exemplo: de.exemplo.com), dependendo da configuração de estrutura de URL abaixo.','Primary language'=>'Idioma principal','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Após alterar o idioma principal, limpe os permalinks (seção abaixo) para atualizar o roteamento de URL.','URL structure'=>'Estrutura de URL','Path prefix — example.com/de/'=>'Prefixo de caminho — exemplo.com/de/','Subdomain — de.example.com/'=>'Subdomínio — de.exemplo.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'O modo de subdomínio requer que o seu servidor web aponte todos os subdomínios de idioma (por exemplo, de.exemplo.com) para esta instalação do WordPress. Após alterar os modos, limpe as regras de permalink e limpe quaisquer caches. Se a sua URL inicial incluir www (por exemplo, www.exemplo.com), use o filtro lf_base_domain para definir o domínio raiz sem o www, para que os subdomínios sejam construídos corretamente.','Browser language redirect'=>'Redirecionamento de idioma do navegador','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Redirecione os visitantes para o seu idioma preferido com base no cabeçalho Accept-Language do navegador','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Quando ativado, os visitantes de primeira viagem sem cookie de idioma e sem prefixo de idioma na URL são redirecionados para a versão de idioma mais próxima. O redirecionamento é ignorado se o idioma preferido do navegador não estiver entre os idiomas ativos do roteador. Uma vez que um visitante seleciona um idioma através do alternador, o cookie tem prioridade e o cabeçalho do navegador é ignorado em visitas futuras.','Save Router Settings'=>'Salvar configurações do roteador','Flush Permalinks'=>'Limpar Permalinks','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenera as regras de reescrita do WordPress para que os prefixos de URL, os slugs específicos de idioma e as reescritas de arquivo estejam sincronizados. Necessário após alterar o idioma principal ou adicionar suporte a novos idiomas.','Flush Permalink Rules'=>'Limpar regras de permalink','Active Languages'=>'Idiomas ativos','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Idiomas atualmente conhecidos pelo roteador (derivados dos pacotes de idioma do WordPress instalados mais o idioma principal). Instale pacotes de idioma adicionais na seção abaixo para disponibilizar mais idiomas para roteamento e tradução.','%d locale pack installed.'=>'%d pacote de idioma instalado.' . "\0" . '%d pacotes de idioma instalados.','Install a Language'=>'Instalar um idioma','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Baixe e instale um pacote de idioma do núcleo do WordPress diretamente do WordPress.org. Uma vez instalado, o idioma fica disponível para roteamento de URL e fluxo de trabalho de tradução AI. A lista de idiomas disponíveis é buscada sob demanda — clique no botão abaixo para carregá-la.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'A instalação de idiomas está desativada neste servidor. A constante DISALLOW_FILE_MODS está definida no wp-config.php. Instale pacotes de idioma manualmente via WP-CLI: wp language core install de_DE','Load available languages'=>'Carregar idiomas disponíveis','— select a language —'=>'— selecione um idioma —','Install'=>'Instalar','Language Setup'=>'Configuração de idioma','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Nenhum idioma secundário configurado. Instale um pacote de idioma acima para ativar a estrutura de modelos.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Selecione um idioma para gerenciar seus modelos FSE, partes de modelos e menus de navegação.','Forbidden'=>'Proibido','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'A instalação de idiomas está desativada neste servidor (DISALLOW_FILE_MODS está definido).','Invalid locale code.'=>'Código de idioma inválido.','Language %s installed successfully.'=>'Idioma %s instalado com sucesso.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Falha na instalação do pacote de idioma. O idioma pode já estar instalado, o código de idioma pode estar incorreto ou seu servidor pode bloquear gravações de arquivos.','Navigations'=>'Navegações','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'A tradução de navegação requer um provedor de IA ativo. Configure uma chave de API na aba Chaves de API.','Navigation'=>'Navegação','Action'=>'Ação','Re-translate'=>'Re-traduzir','CPT Block Patterns'=>'Padrões de blocos CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Padrões de blocos registrados para tipos de posts personalizados. Use o botão Traduzir para produzir uma variante de idioma. O conteúdo traduzido é salvo aqui e pode ser copiado para qualquer post CPT a partir do inseridor de padrões do editor de blocos ou usado como ponto de partida para um Padrão Sincronizado (Bloco Reutilizável).','Pattern'=>'Padrão','Post Types'=>'Tipos de Post','✓ Translation saved'=>'✓ Tradução salva','View'=>'Visualizar','Template Parts'=>'Partes do Modelo','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Cópias específicas de idioma das partes do modelo do tema. Uma vez estruturados, os modelos são atualizados para referenciar a parte específica do idioma.','Part'=>'Parte','Status / Actions'=>'Status / Ações','Fix Links'=>'Corrigir links','Fix Nav'=>'Corrigir navegação','Create'=>'Criar','Templates'=>'Modelos','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Modelos FSE semeados a partir do tema ativo. Crie e personalize no Editor do Site.','Actions'=>'Ações','Fix Parts'=>'Corrigir partes','Create missing'=>'Criar ausentes','Translate all'=>'Traduzir tudo','Fix all parts'=>'Corrigir todas as partes','Fix all links'=>'Corrigir todos os links','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'A testar…','✓ Connection OK'=>'✓ Conexão OK','✗ Failed:'=>'✗ Falhou:','No response from provider — check the error log for details.'=>'Sem resposta do fornecedor — verifique o registo de erros para detalhes.','Network error — could not reach the WordPress AJAX endpoint.'=>'Erro de rede — não foi possível alcançar o endpoint AJAX do WordPress.','Loading…'=>'A carregar…','Installing…'=>'A instalar…','✓ Language installed.'=>'✓ Língua instalada.','✗ Error:'=>'✗ Erro:','Creating…'=>'A criar…','✓ All templates created.'=>'✓ Todos os modelos criados.','Some templates could not be created.'=>'Alguns modelos não puderam ser criados.','✓ All parts created.'=>'✓ Todas as partes criadas.','Some parts could not be created.'=>'Algumas partes não puderam ser criadas.','✓ All translated.'=>'✓ Todas as traduções concluídas.','Some translations failed.'=>'Algumas traduções falharam.','Review carefully — links and slugs not updated.'=>'Revise cuidadosamente — links e slugs não atualizados.','Fixing…'=>'A corrigir…','✓ Links fixed.'=>'✓ Links corrigidos.','Some link fixes failed.'=>'Algumas correções de links falharam.','✓ Parts fixed.'=>'✓ Partes corrigidas.','Some part fixes failed.'=>'Algumas correções de partes falharam.','✓ Nav refs fixed.'=>'✓ Referências de navegação corrigidas.','Some nav ref fixes failed.'=>'Algumas correções de referências de navegação falharam.','✓ Pattern translated.'=>'✓ Padrão traduzido.','Pattern translation failed.'=>'Falha na tradução do padrão.','Hide'=>'Ocultar','Built-in preset instructions:'=>'Instruções predefinidas incorporadas:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Sem instruções predefinidas — cada recurso de IA usa os seus próprios padrões ajustados. Preencha o campo de instruções de prompt personalizado abaixo para adicionar as suas próprias regras para todo o site.','Settings'=>'Configurações','You do not have permission to manage these settings.'=>'Não tem permissão para gerir estas configurações.','Lingua Forge — Settings'=>'Lingua Forge — Configurações','Settings saved.'=>'Configurações guardadas.','Save Settings'=>'Guardar configurações','Standard'=>'Padrão','Technical / Scientific'=>'Técnico / Científico','Legal / Compliance'=>'Legal / Conformidade','Creative / Marketing'=>'Criativo / Marketing','Full Article'=>'Artigo completo','Introduction only'=>'Apenas introdução','Structured Outline'=>'Esboço estruturado','Generate Content'=>'Gerar conteúdo','Hints'=>'Dicas','Key points, ideas, or structure to build from…'=>'Pontos-chave, ideias ou estrutura a partir da qual construir…','Tone'=>'Tom','Output'=>'Saída','Generate Excerpt'=>'Gerar excerto','Generate Meta Description'=>'Gerar descrição meta','Translate Content'=>'Traduzir conteúdo','Mode'=>'Modo','Full post'=>'Post completo','Translate chunk'=>'Traduzir trecho','Target Language'=>'Idioma de destino','Text to translate'=>'Texto a traduzir','Paste a footnote, sentence, or any snippet here…'=>'Cole aqui uma nota de rodapé, frase ou qualquer trecho…','Also generate meta description'=>'Também gerar descrição meta','Translated Names'=>'Nomes traduzidos','Name displayed in this language. Leave empty to use the source name.'=>'Nome exibido neste idioma. Deixe vazio para usar o nome original.','Too many AI requests. Please retry in %d seconds.'=>'Muitas solicitações de IA. Por favor, tente novamente em %d segundos.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Quota diária de IA atingida (%1$d solicitações). Reinicia às %2$s UTC.','View Lingua Forge details'=>'Ver detalhes do Lingua Forge','View details'=>'Ver detalhes','Visit plugin site'=>'Visitar site do plugin','%d language not yet linked'=>'%d idioma ainda não vinculado' . "\0" . '%d idiomas ainda não vinculados','This is the source page. Footnotes are edited directly in the block editor.'=>'Esta é a página fonte. Notas de rodapé são editadas diretamente no editor de blocos.','No source page linked yet.'=>'Ainda não há página fonte vinculada.','The source page has no footnotes.'=>'A página fonte não possui notas de rodapé.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Estas notas de rodapé vêm da página fonte e são exibidas aqui apenas para referência. Adicione-as a esta pág