ale.'=>'Exibe um aviso educado quando a página atual está sendo exibida no seu idioma de origem porque não existe tradução para o idioma do visitante. Impulsionado pelo sinal LINGUAFORGE_LANG_FALLBACK_ACTIVE do roteador Lingua Forge — não emite nada quando existe uma tradução para a localidade solicitada.','block keywordlanguage'=>'idioma','block keywordtranslation'=>'tradução','block keywordfallback'=>'fallback','block keywordi18n'=>'i18n','block keywordlinguaforge'=>'linguaforge']];
